static String encode(String s) {
    StringBuilder out = new StringBuilder();
    int runLength = 0;
    for (int i = 0; i < s.length(); i++) {
        runLength++;
        boolean lastOfRun = i + 1 == s.length() || s.charAt(i + 1) != s.charAt(i);
        if (lastOfRun) {
            out.append(s.charAt(i)).append(runLength);
            runLength = 0;
        }
    }
    return out.toString();
}
